quests[67007] = { id = 67007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archival Assistance", description = "<The crisp, clean lettering, written with an elegant touch, fades quickly into the parchment's wet, smudged ink and a smell reminiscent of spilled, fermented beverage.>\n\nADVENTURE SEEKERS, ARCHIVAL ENTHUSIASTS--\n\nThe archives call to those who seek answers, yearn to discover, and those who wish to reveal secrets of the past, and perhaps, the future!\n\nThis request is not for the faint of heart, nor those of wavering will.\n\nOnly curious and brave adventurers need apply.\n\n- Kemora", completion = "<Kemora turns gracefully to address you. Before speaking, with a smile upon her face, her eyes follow your being from the ground upon which you walk moving upward, slowly, until your eyes meet in a calming gaze.>\n\nIs it answers you seek as well, {race}?\n\nI am ready to speak if you are up for the challenge.", objectives = "Speak with Kemora at the archives in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[67009] = { id = 67009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hornswog Hogwash" }
