quests[69861] = { id = 69861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trilvarus Loreweaver" }
quests[69862] = { id = 69862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save a Slyvern", description = "Now that she's healed, I think Sylvie wants to show us something. \n\nOur work isn't done yet, {name}! Let's see what's upsetting her.", progress = "A cave? Wait, I can hear something inside!", completion = "It's faint, but I can hear what sounds like kits in the cave!\n\nThis is bad...", objectives = "Find out what Sylvie is upset about.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
