quests[69869] = { id = 69869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cataloger's Paradise", description = "<Doc Nanners looks out of breath as he hands you a letter inviting you back to the Dragonscale Expedition Basecamp for training. He eagerly tries to explain.>\n\nKind elf. Proud tiny-man. Many cameras. Yes?\n\n<Doc Nanners nods excitedly, awaiting your response.>", completion = "There are incredible new specimens to catalog everywhere you look!", objectives = "Speak with Cataloger Coralie in the Dragonscale Basecamp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69870] = { id = 69870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pictures with Purpose", completion = "I hope ya brought ya swim trunks. This river be lively!", objectives = "Meet Akunda the Cataloger and Gunner Fren near the Overflowing Rapids.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
