quests[69888] = { id = 69888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unusual Suspects", description = "{name}, you're here. Good. Don't react, but our findings on the titan discs have just been stolen! Other than us, only the Sundered Flame know what we were up to in that facility.\n\nI need ye to take this device and scan some of the suspicious members that have joined us recently. Reveal the spy and recover the data if you can. We cannae allow it to fall into their hands!", progress = "Be quick and be casual. Got it?", completion = "They escaped? That's not good. The Sundered Flame have been one step ahead of us this whole time, and our one advantage has been lost!\n\nFortunately, I created a copy of these findings. I'm a betting gal, but even I've learned to hedge my bets.", objectives = "Scan Suspicious Explorers to reveal the spy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69891] = { id = 69891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lepidoralia the Resplendent" }
quests[69892] = { id = 69892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grumbletrunk" }
quests[69895] = { id = 69895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summoned Destroyer" }
quests[69896] = { id = 69896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disastrous Detour", description = "I knew joining the Dragonscale Expedition meant venturing into dangerous territory. But I was not expecting to fight off elementals!\n\nOur dig site at the Life Vault Ruins is in complete disarray! Stone monstrosities are rising up out of the ground! We called in an elementalist to consult, but I believe she will need all the help she can get.\n\nPerhaps you can help her? Our camp is just across the river.", completion = "Thank you for coming! The Expedition is in desperate need of your help!", objectives = "Meet Elementalist Taiyang in the Life Vault Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69897] = { id = 69897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behavior Analysis \"Homework\"", description = "I need to talk to someone who knows proto-whelps. Like the ones that live in the Wild Preserve! \n\nAre they as angry as the big ones? Do they bite or breathe fire at you?\n\nWhat if I... er... you petted a proto-whelp? Would they know that you're nice and trying to help them?\n\nI'm asking for science, of course. Tyrgon always tells us to test our hippa... no... hypo... hmph! Hyppotatotoast... ugh! THEORIES!\n\nI think they would like petting and it would make them feel good. Could you test that for me?", progress = "Do you think a whelp would feel better if I petted them? I always feel better when I get hurt and mom takes care of me.\n\n<Iyali looks around, avoiding eye contact.>\n\nI know I'm not supposed to touch the animals. It's for my homework on, uh, proto-whelp behavior. And it's due, uh, soon. So...", completion = "So, some proto-whelps like to be petted, but some don't? \n\nThat's not good. What if this one calls its friends? Or what if it's mean? \n\nI mean, this lesson, uh, makes no sense! This, uh, homework is very difficult. \n\nThank you for helping me. I'm sorry if you got hurt...", objectives = "Pet 3 Sleeping Whelps and report back to Iyali.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69898] = { id = 69898, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scientific Meat-thod", description = "So, I have, uh, more homework... Professor Tyrgon's lessons are super tough! He wants us to find out what proto-whelps, uh, eat! Yeah...\n\nI already know the answer! It's riverbeast meat! \n\nCan you bring me a piece of riverbeast meat? Some riverbeast meat would be a great \"visual aid\" for my project.\n\nBut it has to be a REALLY good piece, ok? Like... the ones from Pudgy Riverbeasts. One like a momma proto-drake would give their whelp to make them strong because, uh, it will make Mister Tyrgon happy.", progress = "Mom says food makes everyone happy.\n\nMaybe it will be friends with me then...\n\nI mean, we'll all be friends! And Professor Tyrgon won't give me a bad grade if I make Riverbeast meat part of my project!", completion = "Oh, wow! That's the most delicious-looking meat I've EVER seen! My project will get the BEST grade. The proto-whelp will definitely want this!\n\n<Iyali's expression is suddenly filled with concern.>\n\nOh no! \n\nI mean, uh, everyone will lwant to copy me... for the project!\n\n<Iyali smiles unconvincingly.>", objectives = "Collect 1 piece of Extra-Delicious Riverbeast Meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69899] = { id = 69899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secret Research", description = "I know.. I am acting weird. I'm sorry!\n\nYou probably guessed I am not being truthful.\n\nI can tell you my secret... if you like. But you will have to promise not to tell the adults!", progress = "We found this Injured Proto-Whelp in the Wild Preserve.\n\nThere was an evil Primalist attacking Proto-Dragons and... they hurt this poor little whelpling!\n\nPlease don't yell at us... We just wanted to help!", completion = "They did what? Oh, these younglings... When will they learn? They could have gotten hurt--or captured!\n\nThis is very serious indeed...", objectives = "Help Iyali and their friends.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69900] = { id = 69900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Identifying the Source", description = "Judging by what the children have said, we might have a primalist prowling the Wild Preserve.\n\nThis calls for immediate investigation.\n\nAccording to what other researchers have observed, Primalists like to steal eggs and whelps to infuse them with power and corrupt them. Those that don't acclimate to the process suffer a slow death... not that the primalists seem to care...\n\nWe need them out of the Preserve. Attend to that, and I will try to distract the children. They must not know of this.", progress = "Keep your voice down! Have you done what I asked?", completion = "Thank you, {name}! I'm certain that was... unpleasant.\n\nI'm sure you would prefer to limit your tasks to exploring and researching, but, unfortunately, we sometimes have to get our hands dirty protecting wildlife from those who endanger it.", objectives = "Slay the experimenting primalist in the Wild Preserve.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69901] = { id = 69901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring In the Expert", description = "Did Iyali say how long this creature has been suffering? If it's too injured to eat, we need to treat it quickly.\n\nNormally a Dragonscale Expedition camp would have everything I need to help this whelp, but getting supplies to the \"frontier\" here on the Dragon Isles has proven tricky. There have been significant delays in our supply routes.\n\nBut, fear not. The land itself will provide! If you bring me Sunlight Flowers, I can craft a soothing balm that will calm the drake so I can heal it.", progress = "Sunlight Flowers are very useful resource.\n\nTheir petals and stalks have sedative properties which will ease the whelp's suffering while we heal it.", completion = "Terrific, {name}. \n\nI hope these kids were able to learn something from you. \n\nWhere did they get the idea we wouldn't help them? Helping wildlife is part of our mission. Maybe our pedagogy needs a review...", objectives = "Collect 5 Sunlight Flowers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69902] = { id = 69902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Theory in Practice", description = "{name}, I require your assistance...\n\nI hope no one was expecting me to craft, subdue the whelp, heal, and teach these children all at once! Multitasking like that is certainly overrated. \n\nNow, you can start by using those flowers. I'll need a couple minutes to prepare myself to heal the proto-whelp. \n\nHopefully, the children will find this incident... instructional.", progress = "Where on earth did they get the idea we wouldn't help them? I need to investigate this further...", completion = "Great work, {name}! I hope the younglings learned a valuable lesson... or a memorable one at least. \n\nWe will keep the whelpling here for a while as I need to ascertain the best occasion for returning it to Preserve.\n\nI shall also make you an honorary Brave Researcher. Your commitment was essential for this creature's survival. I'll just advise you to tell me sooner if you see the children plotting something reckless again.\n\nNow, if you excuse me, I must reevaluate my pedagogy. It's clearly not working.", objectives = "Assist Tyrgon to heal the creature.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69904] = { id = 69904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suspiciously Quiet", completion = "<The young vulpera nervously puts his hands behind his back.>\n\nDo we know you? Noriko said not to talk to strangers...", objectives = "Find Noriko's apprentices in Camp Antonidas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69910] = { id = 69910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where is Wrathion?", description = "How unusual.\n\nEbyssian told us that Wrathion would be awaiting our arrival along with an ambassador for Alexstrasza the Life-Binder, Queen of the Dragons.\n\nIt isn't like a dragon to break a promise.\n\nAt least this eager drakonid is here to greet us. Would you kindly inquire into when the others shall arrive?", progress = "Welcome to the Dragon Isles, friend!\n\n... I think I may have already said that. No matter! I am just excited you are here!", completion = "I do not know! As I said, this is my first assignment... Let me think on what to do.", objectives = "Ask Sendrax when the dragons are expected to arrive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69911] = { id = 69911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Excuse the Mess", description = "I wish I knew more about how to welcome you to the Dragon Isles, but I'm only the sentry.\n\n<Sendrax motions to the tower behind her.>\n\nYou could try talking with Ambassador Fastrasz in the visitor center. He might be able to answer more of your questions before the dragons arrive.\n\nMind your step in there. He was clearing out rubble last I saw.", progress = "Ambassador Fastrasz will be eager to meet you.", completion = "The embassy is looking better already!\n\nIs every {race} as helpful as you are? I can't wait to meet more.", objectives = "Help Ambassador Fastrasz restore the embassy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69912] = { id = 69912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My First Real Emergency!", description = "<Sendrax looks puzzled.>\n\nI have never known the majordomo to be late to anything, much less THIS late to something THIS important.\n\nMost unusual...\n\n<Sendrax perks up at a thought.>\n\nI could use my emergency signal flare to alert them to your arrival. Then they would come rushing to greet you immediately!\n\nI've never fired my emergency signal flare before, though...", completion = "Well then, {name}. What do you say? Do you fancy a fight alongside your newfound dragon acquaintances?\n\nI assure you, there is no quicker way to earn their trust.", objectives = "Convince Sendrax to fire her emergency signal flare to alert the dragons of your arrival.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69913] = { id = 69913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Towers of Earthen Power" }
quests[69914] = { id = 69914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Djaradin Have Awoken", description = "I wish we'd time for more pleasant introductions, but we can't all be Chronormu, can we?\n\nI am Selistra, majordomo to Alexstrasza the Life-Binder, Queen of the Dragons.\n\nQueen Alexstrasza asked me to convey her kindest regards and escort you to her at the Life Pools.\n\nBut I'm afraid I must ask for your assistance before we go meet her.\n\nOur ancient rivals, the djaradin, have awoken from their slumber under the earth and have already assaulted a nearby outpost!", progress = "We must do whatever the majordomo asks of us.", completion = "The djaradin have awoken? This is not good, {name}...", objectives = "Receive your orders from Majordomo Selistra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69915] = { id = 69915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Targeted Ads", description = "Hi, hi, hi! You looking for a gig?\n\nWe're doing a BIG opening sale for our new Crafting Order service, and we need to draw attention! But the wind took my flyers and I think some of the local goats ran off with them.\n\nCould you get my flyers back?", progress = "Whoo! Setting up a business is busy, busy, busy!", completion = "Thank you, thank you, thank you! You're the best {name}!", objectives = "Recover flyers from Forkriver and Meddlesome Goats.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69916] = { id = 69916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Famous Frogs" }
quests[69918] = { id = 69918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaking Our Foundations", description = "Djaradin stonebinders are threatening to break the very foundations of the Citadel! They have to be stopped!\n\nWe haven't even had a chance to reclaim the Citadel as our own and yet it might crumble beneath us. We can't let that happen.\n\nDo what you can, {name}... by that I mean kill them!", progress = "Have you saved the foundation of this Citadel?", completion = "I knew you could be counted on. I feel better knowing that the Citadel isn't about to collapse beneath our feet.", objectives = "Slay Stonewrecker Tokara, Molka the Grinder, and the elementals they have unleashed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69919] = { id = 69919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Craft in Need", description = "You seem like a skilled crafter. Would you like to fill some crafting orders for fellow adventurers and get rich, rich, rich?\n\nI'll tell you the rules of working with the Artisan's Consortium, then you can pick up Crafting Orders at any crafting station on the Dragon Isles!", progress = "Business is busy, busy, busy!", completion = "Great, great, great! Keep it up. There's always more orders to fill!", objectives = "Speak with Azley to learn about filling Crafting Orders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69923] = { id = 69923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Primal Threat", description = "Raszageth has wasted no time building up her Primalist forces.\n\nThe Kirin Tor have detected massive storms being unleashed at key points across Kalimdor and the Eastern Kingdoms.\n\nThe Primalists are unleashing the elements to add to their strength. It seems they plan to cause chaos not only in the Dragon Isles, but in the lands of the Alliance and Horde as well.\n\nSeek out the enemy and study their methods. We have to stop them before it's too late.", progress = "I'm afraid this is only the beginning.", completion = "It is good you thwarted their attack, at least for now.\n\n<Khadgar examines the motes you brought him.>\n\nHmm, primal elemental energy. I will take this for further study.", objectives = "Gather 10 Motes of Primal Energy from enemies in active primal storm locations throughout Kalimdor and the Eastern Kingdoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69924] = { id = 69924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Towers of Flaming Power" }
quests[69925] = { id = 69925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calming the Storms", description = "These Primalists are relentless, unleashing elemental devastation across the Eastern Kingdoms and Kalimdor.\n\nYou must show the same determination, {name}. It is the only way to stop them.\n\nFind their next incursion, remove the enemies within the primal storm area before it is too late and foil their efforts.\n\nWe must protect Azeroth!", progress = "Our effort continues.", completion = "Well done. Let us hope that buys us time before their next incursion.", objectives = "Gather 10 Motes of Primal Energy from enemies in active primal storm locations throughout Kalimdor and the Eastern Kingdoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69926] = { id = 69926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Becca Black and the Seven Gnomes", description = "The djaradin have ransacked the Obsidian Citadel and stolen a number of valuable artifacts.\n\nWrathion has tasked us to recover every item taken from the Citadel. My team has located several in the area, but we could use your help.", progress = "Have you found everything on the list?", completion = "Excellent work, {name}. Once we've located more of the stolen artifacts, we'll be sure to call for your help again.", objectives = "Recover the missing artifacts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69927] = { id = 69927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bazual" }
quests[69928] = { id = 69928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liskanoth" }
quests[69929] = { id = 69929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strunraan" }
quests[69930] = { id = 69930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basrikron" }
quests[69931] = { id = 69931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swoop And Grab" }
quests[69932] = { id = 69932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Every Life Counts", description = "Making potions for Gelikyr means that I don't have time for my other duties.\n\nA duck landed in my garden with a broken rib. I've tended to the wound, but her dressing needs replacing. And since you're so eager to help...\n\n<Szareth shoves a list of ingredients into your hand.>\n\nThis is what you'll need. Bring the rest to me.", progress = "Well?", completion = "<Szareth takes the extra pollen and linens, then looks toward their hut.>\n\nDucks have to contend with harpies further up the cliffside. The wounded land here, and I aid them how I can.\n\nI hope this one will make it.", objectives = "Collect ingredients to replace Little Jetstream's dressings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69933] = { id = 69933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curiosity's Price", description = "Look across the ravine, {race}. Primalists attacked Gelikyr Post days ago, and the battle still rages.\n\nThose people need salves and stitching. I can make it for them, but my ingredients are running low. Since you've chosen to intrude upon my home, consider yourself volunteered.\n\nGo to my garden and find the largest vine you can. Snap it from the root, then bring it to me.", progress = "Be quick. A fresh ingredient is a potent ingredient.", completion = "The lasher attacked you?\n\n<Szareth frowns, sniffing at your clothes. Their snout wrinkles in disgust.>\n\nNo wonder--you reek of blood. And not yours, I assume.\n\nWar truly engulfs the Isles.", objectives = "Take a cutting from the Stubborn Vine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69934] = { id = 69934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleeding Hearts", description = "The potions are ready--now to deliver them.\n\nTake one crate to a small cave in the ravine below us. No one will be there to accept it, but you can trust it will be used well.\n\nTake another crate to the infirmary in Gelikyr Post. An old friend tends to the patients there.\n\nI... realize this is not your duty. Nor is it really mine. But you've been surprisingly helpful, and this medicine could save lives.", progress = "Excuse me, I don't have time to chat.", completion = "Szareth wants to heal everyone, no matter the consequences. Rebels, Scalesworn, wildlife: each deserves equal care.\n\nAnd while I might find Szareth's idealism galling, Gelikyr depends on their expertise.\n\nSo my thanks to Szareth--and you as well. These potions will be invaluable.", objectives = "Deliver the Medical Supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69936] = { id = 69936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zambul, Head Vandal", description = "Good work. Those desecrators cannot force any more of my ancestors to fight for them. But the brute yelling out their orders must be handled.\n\nThat is their overseer, Zambul. He must be stopped.\n\nTake him down.", progress = "Did you give Zambul the end he deserves?", completion = "An initiate must not take pleasure in the death of another Maruuk. But Zambul makes that a challenge.", objectives = "Defeat Overseer Zambul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69937] = { id = 69937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sylvan Succor", description = "Ah, {name}, there you are! I've been looking all over for you.\n\nAnother of our local critters has been suffering from a distinct lack of affectionate treat-feeding of late. Won't you go and find them something sweet to snack on?", progress = "Well, {name}? Did you tend to the poor, hungry critter?", completion = "Another day, another delighted little friend! Excellent work, my Sylvan apprentice!", objectives = "Acquire a Tasty Hatchling's Treat and administer it to the Despondent Duckling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69938] = { id = 69938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fishing Frenzy!" }
quests[69939] = { id = 69939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sylvan Succor", description = "Ah, {name}, there you are! I've been looking all over for you.\n\nAnother of our local critters has been suffering from a distinct lack of affectionate treat-feeding of late. Won't you go and find them something sweet to snack on?", progress = "Well, {name}? Did you tend to the poor, hungry critter?", completion = "Another day, another delighted little friend! Excellent work, my Sylvan apprentice!", objectives = "Acquire a Snow in a Cone and administer it to the Overwrought Otter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69940] = { id = 69940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sylvan Succor", description = "Ah, {name}, there you are! I've been looking all over for you.\n\nAnother of our local critters has been suffering from a distinct lack of affectionate treat-feeding of late. Won't you go and find them something sweet to snack on?", progress = "Well, {name}? Did you tend to the poor, hungry critter?", completion = "Another day, another delighted little friend! Excellent work, my Sylvan apprentice.", objectives = "Acquire a Blubbery Muffin and administer it to the Anxious Eft.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69941] = { id = 69941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frozen Victims" }
quests[69942] = { id = 69942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brackenhide Mysteries" }
quests[69944] = { id = 69944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing Storms", description = "Well, that wizard certainly knows how to make an entrance, doesn't he?\n\nWe won't be able to set sail until someone gets those elemental storms under control.\n\nCheck-in with Storm Huntress Suhrakka. She's leading the expedition efforts to investigate the storms and can help outfit you with whatever gear you need.\n\nWhile you handle that, I'll coordinate the rest of the preparations. At least it'll give me some time to read a few more volumes on dragon history before we set sail.", completion = "These storms are wild, dangerous things. If you wish to confront them, you'll want extra protection.\n\nIn my years of hunting, I've gathered many things that helped ward against the wrath of the elements. Perhaps some of them may be of use to you as well.", objectives = "Speak with Storm Huntress Suhrakka at the zeppelin tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69946] = { id = 69946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master of Their Craft", description = "While I was traveling through these plains, I met an old centaur in a cave up north. They had clearly mastered their craft and had wisdom to spare.\n\nThey helped me understand the knowledge I had gained from the Dragon Isles.\n\nIf you're curious about specializing in your profession, seek out the wisdom of this master. Khadin was their name, of Clan Teerai.", progress = "Patience, young one. Rest in knowing that there is much to learn, and that is acceptable.", completion = "If you truly seek my knowledge, you must prove yourself worthy of it.", objectives = "Seek out Master Khadin to learn their professional wisdom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69949] = { id = 69949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extermination" }
