quests[69964] = { id = 69964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Craggravated Elemental" }
quests[69965] = { id = 69965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quality Assurance", description = "Are you looking for work, {class}?\n\nI represent a new trade company, the Artisan's Consortium, which matches artisans and clients through our crafting orders network.\n\nThe Dragonscale Expedition placed an order for some enchanted mining tools. The tools are crafted, but we would like to test them before completing the order.\n\nWe will pay you for your services, of course.", progress = "Do the tools work as intended?", completion = "Thank you for your help, {name}.\n\nIf you ever need items crafted, the Artisan's Consortium is here to provide.", objectives = "Test Haephesta's Tools on nearby geodes for the Artisan's Consortium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
