quests[69976] = { id = 69976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phenran" }
quests[69979] = { id = 69979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Hunt", description = "Wisdom is not gained. It is earned. If you wish to prove yourself worthy, you will do so in the manner of my people: learning as we act.\n\nFind and hunt Thousandmile, the Elderbull, he who has escaped the hunt for generations.\n\nFrom this, you will gain the wisdom you seek.", progress = "Do you return victorious? A great hunt comes with great reward.", completion = "The path to mastery is slow but steady. Honor the journey.\n\nIf you seek additional wisdom, continue the good hunt. There will always be quests in the world, creatures to hunt and learn from.\n\nAnd I shall be here to help you understand the knowledge you gain.", objectives = "Slay Thousandmile the Elderbull.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69980] = { id = 69980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seavine: Fisherman Tinnak's Gift", description = "<You can see the poor fisherman's spectral hand is still gripping a thread woven of a very strong, yet light, kelp. Nunvuq in Iskaara might find a use for that.>", objectives = "Bring the seavine tope to Nunvuq in Iskaara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69981] = { id = 69981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Customer Satisfaction", description = "Hey {class}, got a tick to help with something?\n\nSome of our favorite customers placed recrafting orders through the Artisan's Consortium, but we haven't heard back from them.\n\nIf you run into them, can you check to make sure they're satisfied with their purchases? Gotta keep customers happy, happy, happy!", progress = "<Mahra is whistling to herself as she crafts.>", completion = "Oh no! Bless their soul... <Mahra looks over the equipment.>\n\nIt's all ruined. Spent too long in the elements. \n\nHere, take this and craft some new armor. Or speak with one of the Crafting Orders clerks next to me or in Valdrakken and have someone do it for you. I suggest something for your wrists or chest.\n\nOne other thing. The quality of these reagents isn't great, but you can always have your new equipment recrafted later to raise its quality.", objectives = "Ask the Artisan's Consortium customers if they are happy with their recrafting orders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69983] = { id = 69983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flamecarved Bone", description = "<Mysterious djaradin runes carved into a bone. Talonstalker Kavia might want to see this.>", completion = "This may be important. Thank you for bringing it to us, {name}.", objectives = "Deliver the item to Talonstalker Kavia.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[69984] = { id = 69984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gold-Banded Dragon Tooth", description = "<You have discovered the remnant of a fallen dragon. Exadria might want to see this.>", completion = "It is important that this dragon not be forgotten. Thank you for bringing it to us, {name}.", objectives = "Deliver the item to Exadria.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
