quests[69992] = { id = 69992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sigil of Storms", description = "<Someone with great knowledge of magic may be interested in studying a find such as this.>", completion = "This is outside of my league, magic-wise.\n\nBut I'll get it to Khadgar. Continue to push back the Primalist threat.", objectives = "Deliver the Sigil of Storms to Storm Huntress Suhrakka in Durotar.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
