quests[70021] = { id = 70021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tale of Tapionnuq" }
quests[70025] = { id = 70025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artisan's Supply: Draconium Sickle", description = "You look like someone with nothing to do. How's about employment?\n\nI have a crafting order to fill for the Artisan's Consortium for a draconium sickle. Now I could easily take care of this, but as an apprentice I think it makes more sense for you to take this one on.\n\nCraft the sickle and bring it to the Ruby Lifeshrine, a draenei named Haephesta will pay you for it.", progress = "How can the Artisan's Consortium help you today?", completion = "A delivery! Excellent. Good doing business with you, {name}.", objectives = "Deliver a Draconium Sickle to Haephesta at the Ruby Lifeshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70026] = { id = 70026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artisan's Supply: Lava Beetles", description = "Are you looking for work, herbalist? The Artisan's Consortium asked me to gather some beetles for their customers.\n\nThe land is plentiful, but not so much that I can simply step away and be back with their request.\n\nBut if you venture out, perhaps you could collect a few beetles on your way?", progress = "How can the Artisan's Consortium help you today?", completion = "A delivery! Excellent. Good doing business with you, {name}.", objectives = "Deliver 5 Lava Beetles to Haephesta at the Ruby Lifeshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70027] = { id = 70027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artisan's Supply: Surveyor's Cloth Bands", description = "Are you looking for work, tailor? The Artisan's Consortium asked me to craft some wristbands for their customers.\n\nWhile I appreciate that these explorers are trying to involve themselves with our weaving, I do not have time for such requests.\n\nPerhaps you would be interested in taking on this project?", progress = "How can the Artisan's Consortium help you today?", completion = "A delivery! Excellent. Good doing business with you, {name}.", objectives = "Deliver Surveyor's Cloth Bands to Haephesta at the Ruby Lifeshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70028] = { id = 70028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artisan's Supply: Salt Deposits", description = "Are ye looking for work, miner?\n\nI was talkin' to Haephesta an' she says the Artisan's Consortium is needin' salt for their customers.\n\nNoo I'd do it meself, but, well, I dinna want to.\n\nBe a pal and fetch 'em for 'er, eh?", progress = "How can the Artisan's Consortium help you today?", completion = "A delivery! Excellent. Good doing business with you, {name}.", objectives = "Deliver 5 Salt Deposits to Haephesta at the Ruby Lifeshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70029] = { id = 70029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artisan's Supply: Runed Serevite Rods", description = "You seem to have a magical touch, enchanter. Would you be able to help with an order I've got?\n\nThe Artisan's Consortium has requested several rods made of Serevite for a customer, but enchanting rods aren't quite my specialty.\n\nIf you're willing, Haephesta at the Ruby Lifeshrine will compensate you for your time and effort!", progress = "How can the Artisan's Consortium help you today?", completion = "A delivery! Excellent. Good doing business with you, {name}.", objectives = "Deliver 2 Runed Serevite Rods to Haephesta at the Ruby Lifeshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70030] = { id = 70030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artisan's Supply: Quality-Assured Optics", description = "Ah, an engineer! Excellent timing.\n\nI've got some schematics to fix, but some tall lady came by asking for a set of optics.\n\nYou know how to make those, right?\n\nTake 'em to the Ruby Lifeshrine when you have 'em crafted. I think she said she was with the Artisan's Consortium or something.", progress = "How can the Artisan's Consortium help you today?", completion = "A delivery! Excellent. Good doing business with you, {name}.", objectives = "Deliver a pair of Quality-Assured Optics to Haephesta at the Ruby Lifeshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70031] = { id = 70031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artisan's Supply: Chef's Smooth Rolling Pin", description = "Are you looking for work, scribe?\n\nI received an order from a company called the Artisan's Consortium.\n\nIt seems like a simple enough task for an apprentice crafter such as yourself.", progress = "How can the Artisan's Consortium help you today?", completion = "A delivery! Excellent. Good doing business with you, {name}.", objectives = "Deliver a Chef's Smooth Rolling Pin to Haephesta at the Ruby Lifeshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70032] = { id = 70032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artisan's Supply: Jeweler's Specs", description = "Are you looking for work, jewelcrafter? The Artisan's Consortium asked me to craft some spectacles for their customers. \n\nMe! Like I have time for this.\n\nYou can do it, yeah?", progress = "How can the Artisan's Consortium help you today?", completion = "A delivery! Excellent. Good doing business with you, {name}.", objectives = "Deliver Sundered Onyx Loupes to Haephesta at the Ruby Lifeshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70033] = { id = 70033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artisan's Supply: Pioneer's Leather Boots", description = "Are you looking for work, leatherworker? The Artisan's Consortium asked me to craft some boots for their customers.\n\nClearly they don't understand my popularity. Do you know how many explorers have come through today complaining of holes in their shoes?\n\nIf you have the time, take these measurements. Perhaps this Artisan's Consortium could be a promising business opportunity for you.", progress = "How can the Artisan's Consortium help you today?", completion = "A delivery! Excellent. Good doing business with you, {name}.", objectives = "Deliver Pioneer's Leather Boots to Haephesta at the Ruby Lifeshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70034] = { id = 70034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artisan's Supply: Salamanther Scales", description = "Are you looking for work, skinner? The Artisan's Consortium asked me to gather the scales of a salamanther for their customers.\n\nI may be an artisan, but I am no one's errand child!\n\nBut... ah, perhaps you could find some?", progress = "How can the Artisan's Consortium help you today?", completion = "A delivery! Excellent. Good doing business with you, {name}.", objectives = "Deliver 3 Salamanther Scales to Haephesta at the Ruby Lifeshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70035] = { id = 70035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruriq's River Rapids Ride" }
quests[70037] = { id = 70037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unpowered Tools" }
quests[70040] = { id = 70040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tumbling Through Time", description = "When the magic of Bronze and Infinite collided, it sent Chronormu and Eternus into an uncontrolled tumble through time.\n\nAs they fall, they rip the fabric of time itself, sending out countless ripples across time and space. We must locate them and bring them back. Only then will we be able to stop any further damage. I see that you will be the one to stop Chronormu's fall.\n\nI would ask that you to gather the allies you will need to save Chronormu, while I focus on her magic.", progress = "Quickly. Even we do not have time to waste.", completion = "If we work quickly, I believe we may be able to catch her.", objectives = "Gather your allies and then speak with Nozdormu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70041] = { id = 70041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Storm-Eater's Fury", description = "Raszageth is attempting to rip all the arcane magic out of the tower so she can destroy it!\n\nKalecgos is doing what he can to hold her back, and I am using my magic to try to replenish the ley energy.\n\nI fear we will not last much longer. As we speak, more Primalists make their way up here to overwhelm us!\n\nTake my modified Arcane Disc. Hold off the incoming Primalists... and let us hope for a miracle.", completion = "Raszageth has fled, Vakthros is stabilized... and more blue dragons have arrived.\n\nI think we can rest for a moment now.", objectives = "Ride Khadgar's flying disc and hold off the Primalist army.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70042] = { id = 70042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opportunities Abound", description = "Ya scared me, thought I was nabbed!\n\nLook at all the brave explorers ready to conquer the Dragon Isles... packs bulging with tools and equipment.\n\nWe could get rich here!\n\nCheck around see if you can grab a few items, and I'll cut you in on the profits.", progress = "You find what we was looking for?", completion = "See, I told ya we'd make a profit.", objectives = "Acquire several items for Vish the Sneak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70047] = { id = 70047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Icy Prisons" }
quests[70048] = { id = 70048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Primal Threat", description = "Raszageth has wasted no time building up her Primalist forces.\n\nThe Kirin Tor have detected massive storms being unleashed at key points across Kalimdor and the Eastern Kingdoms.\n\nThe Primalists are unleashing the elements to add to their strength. It seems they plan to cause chaos not only in the Dragon Isles, but in the lands of the Alliance and Horde as well.\n\nSeek out the enemy and study their methods. We have to stop them before it's too late.", progress = "I'm afraid this is only the beginning.", completion = "It is good you thwarted their attack, at least for now.\n\n<Khadgar examines the motes you brought him.>\n\nHmm, primal elemental energy. I will study this further.", objectives = "Gather 10 Motes of Primal Energy from enemies in active primal storm locations throughout Kalimdor and the Eastern Kingdoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70049] = { id = 70049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calming the Storms", description = "These Primalists are relentless, unleashing elemental devastation across the Eastern Kingdoms and Kalimdor.\n\nYou must show the same determination, {name}. It is the only way to stop them.\n\nFind their next incursion, remove the enemies within the primal storm area before it is too late and foil their efforts.\n\nWe must protect Azeroth!", progress = "Our effort continues.", completion = "Well done. Let's hope that buys us time before their next incursion.", objectives = "Gather 10 Motes of Primal Energy from enemies in active primal storm locations throughout Kalimdor and the Eastern Kingdoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70050] = { id = 70050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing Storms", description = "So the handsome fellas are sendin' ye on a wee adventure, eh?\n\nThat's fine. The expedition won't be able to set sail until someone gets those elemental storms under control anyway.\n\nCheck-in with Storm Hunter William. He's leading the expedition efforts to investigate the storms and can outfit ye with whatever gear you need.\n\nI'll coordinate the rest of the preparations here while ye have all the fun out there.\n\nYe'll owe me one, though!", completion = "If you're heading into those storms, you're going to need all the help you can get.\n\nLucky for you, I've been stocking up on storm-chasing gear for years.\n\nTake a look, and see what fits.", objectives = "Speak with Storm Hunter William in Stormwind Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70051] = { id = 70051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cliffside Circuit", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70052] = { id = 70052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cliffside Circuit - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70055] = { id = 70055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sigil of Storms", description = "<Someone with great knowledge of magic may be interested in studying a find such as this.>", completion = "This is outside of my league, magic-wise.\n\nBut I'll get it to Khadgar. Continue to push back the Primalist threat.", objectives = "Deliver the Sigil of Storms to Storm Hunter William in Stormwind.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[70057] = { id = 70057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thieving Tarasek" }
quests[70058] = { id = 70058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friend on the Mend", description = "Happy Duck got hurt while we were flying around... He was doing so good and then I... I hit a tree!\n\n<Lillistrasza gestures mournfully at the damaged duck plushie on her head.>\n\nHis stuffing is falling out! His feathers are all bent! One of his eyes is gone! Noooo!\n\nYou can help fix Happy Duck, right?", progress = "Yes? Anything to help!", completion = "Yes, yes! These materials should be plenty to repair your Happy Duck, young one.\n\n<Mahra smiles at you.>\n\nThank you for bringing this important matter to my attention, {name}. It should only take me a moment.", objectives = "Collect 5 Soft Ruby Feathers, 3 Scraps of Fabric, and 1 Glass Bead from around the Ruby Lifeshrine to help repair Happy Duck.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
